const p = $json;
const out = { json: {
  pdf_file_name: p.pdf_file_name || 'worksheet.pdf',
  subject_title: p.subject_title || '',
  age_group: p.age_group || '',
  tpt_kit: p.tpt_kit || '',
  missing_pages: p.missing_pages || 0
}, binary: {} };

if (p.pdf_url) {
  const buf = await this.helpers.httpRequest({ url: p.pdf_url, method: 'GET', encoding: 'arraybuffer', json: false, timeout: 120000 });
  out.binary.data = await this.helpers.prepareBinaryData(Buffer.from(buf), out.json.pdf_file_name, 'application/pdf');
}

const coverName = out.json.pdf_file_name.replace(/\.pdf$/i, '') + '_COVER.jpg';
// 1x1 fallback กันอีเมลล้มถ้าไม่มีภาพปกเลย
const onePx = '/9j/4AAQSkZJRgABAQEAYABgAAD/2wBDAP//////////////////////////////////////////////////////////////////////////////////////wgALCAABAAEBAREA/8QAFBABAAAAAAAAAAAAAAAAAAAAAP/aAAgBAQABPxA=';
out.binary.cover = await this.helpers.prepareBinaryData(Buffer.from(p.cover_b64 || onePx, 'base64'), coverName, 'image/jpeg');

return [out];
